class Solution:
    def longestValidParentheses(self, s: str) -> int:
        if not s:
            return 0

        res = 0
        stack = [-1]  # 哨兵：作为计算长度的基准

        for i in range(len(s)):
            if s[i] == '(':
                stack.append(i)   # 左括号：记录下标
            else:
                stack.pop()       # 右括号：弹出栈顶（尝试匹配）
                if not stack:
                    stack.append(i)  # 无法匹配，此 ')' 成为新基准
                else:
                    res = max(res, i - stack[-1])  # 当前有效串长度

        return res
